def _ensure_canvas_and_callbacks(self):
        if self.canvas is None:
            self.canvas = self.parent.figure.canvas
            self.cids = {
                'motion_notify_disconnect': self.canvas.mpl_connect('motion_notify_event', self.on_motion),
                'pick_event_disconnect': self.canvas.mpl_connect('pick_event', self.on_pick),
                'button_release_disconnect': self.canvas.mpl_connect('button_release_event', self.on_release)
            }

def on_motion(self, event):
        self._ensure_canvas_and_callbacks()
        if self.artist is not None:
            self.artist.set_x(event.xdata)
            self.artist.set_y(event.ydata)
            self.artist.figure.canvas.draw_idle()

def on_pick(self, event):
        self._ensure_canvas_and_callbacks()
        if event.artist == self.artist:
            self.press = event.xdata, event.ydata
            self.artist.set_pickradius(10000)  # make picking easier
            self.artist.figure.canvas.draw_idle()

def disconnect(self):
        if self.canvas is not None and self.cids is not None:
            for cid in self.cids.values():
                self.canvas.mpl_disconnect(cid)
            self.canvas = None
            self.cids = None
